// Kairo brand artwork: the symbol, the character and its faces, drawn once as
// plain paths. The colors are fixed brand artwork, not theme values: the
// character reads the same on every background. Layers stack back to front:
// I, O, K, A, R, then the face. The path data is not meant to be edited by hand.

type FaceElement =
  | { readonly shape: 'ellipse'; readonly cx: number; readonly cy: number; readonly rx: number; readonly ry: number }
  | { readonly shape: 'path'; readonly d: string }

type StrokeFace = { readonly transform: string; readonly strokeWidth: number; readonly elements: readonly FaceElement[] }

